import heapq

def match(orders):
    trades = []
    book_buys = []   # heap of (-price, seq, id)
    book_sells = []  # heap of (price, seq, id)
    orders_map = {}  # id -> dict(side, price, qty, seq)

    def clean_top(heap):
        while heap:
            top = heap[0]
            o_id = top[2]
            order = orders_map.get(o_id)
            if order is None or order['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return order, o_id
        return None, None

    def do_match(incoming_id, side, price, qty, is_market):
        nonlocal trades
        if side == 'buy':
            opposite = book_sells
            while qty > 0:
                order, o_id = clean_top(opposite)
                if order is None:
                    break
                if not is_market and order['price'] > price:
                    break
                trade_qty = min(qty, order['qty'])
                trades.append([incoming_id, o_id, order['price'], trade_qty])
                qty -= trade_qty
                order['qty'] -= trade_qty
                if order['qty'] == 0:
                    heapq.heappop(opposite)
                    del orders_map[o_id]
            return qty
        else:
            opposite = book_buys
            while qty > 0:
                order, o_id = clean_top(opposite)
                if order is None:
                    break
                if not is_market and order['price'] < price:
                    break
                trade_qty = min(qty, order['qty'])
                trades.append([o_id, incoming_id, order['price'], trade_qty])
                qty -= trade_qty
                order['qty'] -= trade_qty
                if order['qty'] == 0:
                    heapq.heappop(opposite)
                    del orders_map[o_id]
            return qty

    for seq, o in enumerate(orders):
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            if oid in orders_map:
                del orders_map[oid]
            continue

        if typ == 'market':
            _, oid, side, qty = o
            price = None
            is_market = True
        else:
            _, oid, side, price, qty = o
            is_market = (typ == 'ioc')

        remaining = do_match(oid, side, price, qty, is_market)

        if typ == 'limit' and remaining > 0:
            order = {'side': side, 'price': price, 'qty': remaining, 'seq': seq}
            orders_map[oid] = order
            if side == 'buy':
                heapq.heappush(book_buys, (-price, seq, oid))
            else:
                heapq.heappush(book_sells, (price, seq, oid))
        # ioc and market discard remainder

    return trades

